mapper.select:
SELECT * FROM ( SELECT c.*, CASE WHEN c.check_time IS NULL AND c.commit_time IS NULL THEN 1 WHEN c.check_time IS NOT NULL AND c.commit_time IS NULL THEN 2 WHEN c.check_time IS NOT NULL AND c.commit_time IS NOT NULL THEN 3 ELSE 0 END AS check_status, CASE WHEN c.overdue_days > 0 THEN 1 ELSE 0 END AS overdue, p.plan_name, p.dead_line, p.plan_type, p.plan_status, p.id as checkPlanClientId, (SELECT rm.report_type FROM new_after_lease_check_report_meta rm WHERE rm.check_plan_client_id = c.id ORDER BY rm.id DESC LIMIT 1) AS report_type FROM new_after_lease_check_plan_client c INNER JOIN new_after_lease_check_plan_base p ON c.plan_id = p.id ) AS result
result.plan_status != 'PUBLISH' and result.approval_status not in('CANCELED','CANCEL')
and result.belong_dept_id in
#{belongDeptId}
and result.dead_line >= #{dto.deadLineFrom} and result.dead_line <= #{dto.deadLineTo} and result.overdue = #{dto.overdue}
AND result.check_status IN (0, 1)
AND result.check_status = #{dto.checkStatus}
order by result.create_time desc
